_NUMERIC_ONLY_LINE_RE = re.compile(r"^[\d\$\.,\s%]+$")
# Amount-led lines ("$1,234.00 ...", "1,234.00 CR"); a creditor name that merely
# starts with digits ("1ST FRANKLIN FINANCIAL", "53 CARD") is not an amount.
_LEADING_AMOUNT_RE = re.compile(r"^\$|^\d{1,3}(?:,\d{3})+(?:\.\d+)?\b|^\d+\.\d{2}\b")


def is_plausible_creditor_line(line: str) -> bool:
    line = line.strip()
    if len(line) < 2 or len(line) > 80:
        return False
    if _SKIP_CREDITOR_LINES.match(line):
        return False
    if is_city_state_line(line):
        return False
    if re.match(r"^\d{3}[-\s]?\d{2}[-\s]?\d{4}$", line):
        return False
    if _NUMERIC_ONLY_LINE_RE.match(line):
        return False
    if _LEADING_AMOUNT_RE.match(line):
        return False
    if line.lower().startswith("http"):
        return False
    return bool(re.search(r"[A-Za-z]", line))

