_UNKNOWN_CREDITOR = frozenset({"unknown", "unknown creditor", "n/a", "na"})


def _normalized_creditor(creditor: str) -> str:
    """Case- and whitespace-insensitive form used for filler/duplicate matching."""
    return " ".join((creditor or "").split()).lower()


def is_junk_creditor_name(creditor: str) -> bool:
    name = (creditor or "").strip()
    if not name:
        return True
    if not is_plausible_creditor_line(name):
        return True
    if _normalized_creditor(name) in _UNKNOWN_CREDITOR:
        return True

