def tradeline_dedupe_key(creditor: str, account_number: str) -> str:
    """Identity key for a tradeline: creditor capitalisation/spacing is not significant."""
    return f"{_normalized_creditor(creditor)}|{(account_number or '').strip().lower()}"


def dedupe_tradelines(tradelines: List[ParsedTradeline]) -> List[ParsedTradeline]:
    seen: set[str] = set()
    out: List[ParsedTradeline] = []
    for tl in tradelines:
        key = tradeline_dedupe_key(tl.creditor, tl.account_number)
        if key in seen:
            continue
        seen.add(key)
        out.append(tl)
    return out

